import { FormEvent, useEffect, useMemo, useState } from "react";
import { createRoot } from "react-dom/client";
import "./style.css";

type Book = { title: string; totalPages: number };
type Entry = { date: string; pages: number };
const BOOK_KEY = "reading-desk-book";
const ENTRIES_KEY = "reading-desk-entries";

const today = () => new Date().toISOString().slice(0, 10);
const formatDate = (date: string) => new Intl.DateTimeFormat("zh-CN", { month: "long", day: "numeric", weekday: "short" }).format(new Date(`${date}T12:00:00`));
const formatShortDate = (date: string) => new Intl.DateTimeFormat("zh-CN", { month: "numeric", day: "numeric" }).format(new Date(`${date}T12:00:00`));

function readStorage<T>(key: string, fallback: T): T {
  try { const value = localStorage.getItem(key); return value ? JSON.parse(value) as T : fallback; } catch { return fallback; }
}

function calculateStreak(entries: Entry[]) {
  const dates = new Set(entries.filter((entry) => entry.pages > 0).map((entry) => entry.date));
  let cursor = new Date(`${today()}T12:00:00`);
  if (!dates.has(today())) cursor.setDate(cursor.getDate() - 1);
  let streak = 0;
  while (dates.has(cursor.toISOString().slice(0, 10))) { streak += 1; cursor.setDate(cursor.getDate() - 1); }
  return streak;
}

function App() {
  const [book, setBook] = useState<Book | null>(() => readStorage<Book | null>(BOOK_KEY, null));
  const [entries, setEntries] = useState<Entry[]>(() => readStorage<Entry[]>(ENTRIES_KEY, []));
  const [showSetup, setShowSetup] = useState(() => !readStorage<Book | null>(BOOK_KEY, null));
  const [setupTitle, setSetupTitle] = useState(() => book?.title ?? "");
  const [setupPages, setSetupPages] = useState(() => book?.totalPages?.toString() ?? "");
  const [entryPages, setEntryPages] = useState("");
  const [entryDate, setEntryDate] = useState(today());
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");

  useEffect(() => { localStorage.setItem(BOOK_KEY, JSON.stringify(book)); }, [book]);
  useEffect(() => { localStorage.setItem(ENTRIES_KEY, JSON.stringify(entries)); }, [entries]);

  const stats = useMemo(() => {
    const readPages = entries.reduce((sum, entry) => sum + entry.pages, 0);
    const total = book?.totalPages ?? 0;
    return { readPages, total, remaining: Math.max(total - readPages, 0), percent: total ? Math.min(100, Math.round((readPages / total) * 100)) : 0, streak: calculateStreak(entries) };
  }, [book, entries]);
  const todayEntry = entries.find((entry) => entry.date === today());

  const saveBook = (event: FormEvent) => {
    event.preventDefault();
    const title = setupTitle.trim();
    const totalPages = Number(setupPages);
    if (!title) { setError("请写下书名。"); return; }
    if (!Number.isInteger(totalPages) || totalPages <= 0) { setError("目标页数需要是大于 0 的整数。"); return; }
    setBook({ title, totalPages }); setShowSetup(false); setError(""); setNotice("书籍信息已保存");
  };

  const saveEntry = (event: FormEvent) => {
    event.preventDefault();
    if (!book) return;
    const pages = Number(entryPages);
    const previous = entries.find((entry) => entry.date === entryDate)?.pages ?? 0;
    const available = stats.remaining + previous;
    if (!Number.isInteger(pages) || pages < 0) { setError("请输入 0 或更大的整数页数。"); return; }
    if (pages > available) { setError(`这本书还剩 ${available} 页，不能超过剩余页数。`); return; }
    setEntries((current) => [...current.filter((entry) => entry.date !== entryDate), { date: entryDate, pages }].sort((a, b) => b.date.localeCompare(a.date)));
    setEntryPages(""); setError(""); setNotice(entryDate === today() ? "今天的阅读已记录" : "阅读记录已保存");
  };

  const deleteEntry = (date: string) => { setEntries((current) => current.filter((entry) => entry.date !== date)); setNotice("记录已删除"); };

  if (showSetup || !book) return (
    <main className="setup-page"><div className="paper-mark">READING DESK / 01</div><section className="setup-wrap">
      <p className="eyebrow">你的私人阅读台</p><h1>让每一页，<br /><em>都有来处。</em></h1><p className="setup-copy">从正在读的那一本开始。记录步伐，回头时就能看见自己走了多远。</p>
      <form className="setup-form" onSubmit={saveBook}><label>书名<input autoFocus value={setupTitle} onChange={(e) => setSetupTitle(e.target.value)} placeholder="例如：百年孤独" /></label><label>全书页数<input type="number" min="1" step="1" value={setupPages} onChange={(e) => setSetupPages(e.target.value)} placeholder="例如：360" /></label>{error && <p className="form-error" role="alert">{error}</p>}<button className="primary-button" type="submit">开始这段阅读 <span>→</span></button></form>
      <p className="privacy-note">数据只保存在这台设备的浏览器里</p>
    </section></main>
  );

  return <main className="app-shell">
    <header className="topbar"><div className="brand"><span className="brand-dot" />READING DESK</div><button className="text-button" type="button" onClick={() => { setSetupTitle(book.title); setSetupPages(book.totalPages.toString()); setShowSetup(true); }}>编辑书籍 <span>↗</span></button></header>
    <div className="intro"><div><p className="eyebrow">正在阅读 / IN PROGRESS</p><h1>把阅读，<br /><em>变成日常。</em></h1></div><p className="date-stamp">{formatDate(today())}<br /><span>保持一点好奇。</span></p></div>
    {notice && <div className="notice" role="status">{notice}<button type="button" aria-label="关闭提示" onClick={() => setNotice("")}>×</button></div>}
    <section className="dashboard-grid">
      <article className="progress-feature"><div className="section-kicker">CURRENT BOOK <span>01</span></div><h2>{book.title}</h2><p className="book-meta">目标 {book.totalPages.toLocaleString()} 页 <span>·</span> {stats.remaining > 0 ? `还有 ${stats.remaining} 页` : "已读完这本书"}</p><div className="progress-figure"><strong>{stats.percent}<small>%</small></strong><span>完成度</span></div><div className="progress-track"><div style={{ width: `${stats.percent}%` }} /></div><div className="progress-foot"><span>已读 {stats.readPages} 页</span><span>{stats.total} 页</span></div><div className="bookmark">{stats.percent}<small>%</small></div></article>
      <aside className="entry-panel"><div className="section-kicker">DAILY LOG <span>02</span></div><h2>今天读了多少？</h2><p className="panel-copy">哪怕只有几页，也值得被记住。</p><form onSubmit={saveEntry}><label>日期<input type="date" value={entryDate} max={today()} onChange={(e) => setEntryDate(e.target.value)} /></label><label>阅读页数<div className="page-input"><input autoFocus inputMode="numeric" type="number" min="0" step="1" value={entryPages} onChange={(e) => setEntryPages(e.target.value)} placeholder={todayEntry ? String(todayEntry.pages) : "0"} /><span>页</span></div></label>{error && <p className="form-error" role="alert">{error}</p>}<button className="primary-button" type="submit">保存今天的阅读 <span>↗</span></button></form><p className="entry-hint">同一天再次保存，会更新这条记录</p></aside>
